def clean(df):
    df = df.copy()
    df['Category'] = df['Category'].str.strip()
    df['Revenue'] = df['Quantity'] * df['Price']
    return df

def answer(df):
    df = clean(df)
    df = df.dropna(subset=['Category'])
    result = df.groupby('Category')['Revenue'].sum()
    return {str(k): float(v) for k, v in result.items()}
